def normalize_labels(values):
    """Return stripped, lowercase, nonempty labels in input order."""
    labels = []
    for value in values:
        label = value.strip().lower()
        if label:
            labels.append(label)
    return labels

from src.normalize import normalize_labels
from src.render import render_labels

def summarize_labels(values):
    return render_labels(normalize_labels(values))

